use xiom.io;
fn apply_discount(price: Float64, percent: Float64) -> Float64 {
  return price * (1.0 - percent / 100.0);
}

fn add_tax(price: Float64, rate: Float64) -> Float64 {
  return price * (1.0 + rate / 100.0);
}

fn main() {
  let after_discount = apply_discount(200.0, 25.0);
  let total = add_tax(after_discount, 10.0);
  io.println("Total: $92");
}
